// Pointer cast
Base* base = /* ... */;
Derived* derived = dynamic_cast<Derived*>(base);
if (derived) { /* success */ } else { /* failed, base is not Derived */ }

// Reference cast (throws on failure)
try {
    Derived& derived = dynamic_cast<Derived&>(base_ref);
    // success
} catch (std::bad_cast& e) {
    // failed
}

// Pointer to void (most derived object)
void* most_derived = dynamic_cast<void*>(base);

// Rvalue reference (C++11)
Derived&& temp = dynamic_cast<Derived&&>(get_base());

// Invalid: cannot cast away const
const Base* cb = /* ... */;
Derived* d = dynamic_cast<Derived*>(cb);  // Error!
const Derived* cd = dynamic_cast<const Derived*>(cb);  // OK

