#include <iostream>
#include <typeinfo>
#include <exception>

// Example from standard: virtual inheritance
class A { 
public:
    virtual void f() { std::cout << "A::f()\n"; }
    virtual ~A() = default;
};

class B { 
public:
    virtual void g() { std::cout << "B::g()\n"; }
    virtual ~B() = default;
};

class D : public virtual A, private B { 
public:
    void demo() { std::cout << "D::demo()\n"; }
};

class E : public D, public B { };
class F : public E, public D { };

void demonstrate_dynamic_cast() {
    std::cout << "=== Basic dynamic_cast scenarios ===\n\n";

    D d;
    B* bp = (B*)&d;  // C-style cast needed (private inheritance)
    A* ap = &d;      // Public derivation, implicit conversion

    std::cout << "1. Downcast from private base (fails):\n";
    try {
        D& dr = dynamic_cast<D&>(*bp);  // Fails: B is private base
        std::cout << "   Success (unexpected!)\n";
    } catch (std::bad_cast& e) {
        std::cout << "   Failed: " << e.what() << " (expected - private base)\n";
    }

    std::cout << "\n2. Cross-cast A* -> B* (fails):\n";
    bp = dynamic_cast<B*>(ap);  // Fails: B is private in D
    std::cout << "   Result: " << (bp ? "success" : "nullptr (expected)") << "\n";

    std::cout << "\n3. Downcast A* -> D* (succeeds):\n";
    D* dp = dynamic_cast<D*>(ap);  // Succeeds: public derivation
    std::cout << "   Result: " << (dp ? "success" : "nullptr") << "\n";
    if (dp) dp->demo();

    std::cout << "\n4. Cast to void* (most derived object):\n";
    void* vp = dynamic_cast<void*>(ap);
    std::cout << "   Got pointer to most derived object: " << vp << "\n";
    std::cout << "   Original D object address: " << &d << "\n";
    std::cout << "   Match: " << (vp == &d ? "yes" : "no") << "\n";
}

void demonstrate_ambiguous_base() {
    std::cout << "\n=== Ambiguous base (multiple inheritance) ===\n\n";

    F f;
    A* ap = &f;  // Succeeds: finds unique A through virtual inheritance

    std::cout << "1. Downcast to D (ambiguous - F has TWO D subobjects):\n";
    D* dp = dynamic_cast<D*>(ap);  // Fails: ambiguous
    std::cout << "   Result: " << (dp ? "success" : "nullptr (expected)") << "\n";

    std::cout << "\n2. Downcast to E (succeeds - unique path):\n";
    E* ep = dynamic_cast<E*>(ap);  // Succeeds: unambiguous E
    std::cout << "   Result: " << (ep ? "success" : "nullptr") << "\n";
}

void demonstrate_safe_downcast() {
    std::cout << "\n=== Safe downcast pattern ===\n\n";

    class Shape { 
    public:
        virtual void draw() = 0;
        virtual ~Shape() = default;
    };

    class Circle : public Shape {
    public:
        void draw() override { std::cout << "Drawing circle\n"; }
        void setRadius(double r) { radius = r; }
    private:
        double radius = 1.0;
    };

    class Rectangle : public Shape {
    public:
        void draw() override { std::cout << "Drawing rectangle\n"; }
        void setWidth(double w) { width = w; }
    private:
        double width = 1.0;
    };

    Shape* shapes[] = { new Circle, new Rectangle, new Circle };

    for (int i = 0; i < 3; ++i) {
        std::cout << "Shape " << i << ": ";

        // Safe downcast - check actual type
        if (Circle* c = dynamic_cast<Circle*>(shapes[i])) {
            std::cout << "is Circle\n";
            c->setRadius(5.0);
        } else if (Rectangle* r = dynamic_cast<Rectangle*>(shapes[i])) {
            std::cout << "is Rectangle\n";
            r->setWidth(10.0);
        }
    }

    for (auto* s : shapes) delete s;
}

int main() {
    demonstrate_dynamic_cast();
    demonstrate_ambiguous_base();
    demonstrate_safe_downcast();

    return 0;
}

// Output:
// === Basic dynamic_cast scenarios ===
//
// 1. Downcast from private base (fails):
//    Failed: std::bad_cast (expected - private base)
//
// 2. Cross-cast A* -> B* (fails):
//    Result: nullptr (expected)
//
// 3. Downcast A* -> D* (succeeds):
//    Result: success
//    D::demo()
//
// 4. Cast to void* (most derived object):
//    Got pointer to most derived object: 0x...
//    Original D object address: 0x...
//    Match: yes
//
// === Ambiguous base (multiple inheritance) ===
//
// 1. Downcast to D (ambiguous - F has TWO D subobjects):
//    Result: nullptr (expected)
//
// 2. Downcast to E (succeeds - unique path):
//    Result: success
//
// === Safe downcast pattern ===
//
// Shape 0: is Circle
// Shape 1: is Rectangle
// Shape 2: is Circle
